(function(){
'use strict';
const api=HubApi,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',calendar:'M4 5h16v16H4z M8 3v4m8-4v4M4 10h16',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',check:'m5 12 4 4L19 6',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',back:'M19 12H5m5-5-5 5 5 5',external:'M14 3h7v7m0-7-11 11M10 3H3v18h18v-7',box:'m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 5 9-5m-9 5v9',building:'M4 21V4h16v17M2 21h20M8 8h1m6 0h1M8 12h1m6 0h1m-5 9v-5h4v5',chart:'M4 20V9m7 11V4m7 16v-7M2 21h20',book:'M12 5v16M12 5C9 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-2-10 1',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.8M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m8 0a4 4 0 0 1 0 8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0M12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l4 2',ticket:'M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4zM15 5v3m0 3v2m0 3v3',award:'M12 3a6 6 0 1 0 0 12 6 6 0 0 0 0-12M8 14l-1 8 5-3 5 3-1-8',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-5',plus:'M12 4v16M4 12h16',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',qr:'M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h4v4h-6zM21 12h-3m-6 0v4',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',bell:'M6 9a6 6 0 0 1 12 0v6l3 3H3l3-3zm4 12h4',logout:'M9 3H3v18h6m6-14 5 5-5 5m5-5H9',copy:'M9 9h12v12H9zM15 6V3H3v12h3',edit:'m14 4 6 6M3 21l5-1L21 7l-5-5L3 15z',mail:'M3 5h18v14H3zM3 5l9 7 9-7',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 8v6m0-10v1'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const fullDate=v=>new Intl.DateTimeFormat('ms-MY',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(v+'T00:00:00Z'));
const shortDate=v=>new Intl.DateTimeFormat('ms-MY',{day:'numeric',month:'short',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(v+'T00:00:00Z'));
const localTime=v=>v?new Date(v).toLocaleString('ms-MY',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Kuala_Lumpur'}):'—';
const malaysiaToday=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kuala_Lumpur'});
const eventPhase=p=>USTPEvents.phase(p),certificateRoute=p=>'#/program/'+encodeURIComponent(p.id)+'/sijil';
const status=p=>p.status==='draft'?'<span class="pill gray">Draf</span>':`<span class="pill ${eventPhase(p)==='ongoing'?'event-live':eventPhase(p)==='finished'?'event-finished':'gray'}">${USTPEvents.label(p)}</span>`;
const modules=[{title:'Pengurusan Aset',text:'Semak ketersediaan, urus pinjaman dan pemulangan aset.',icon:'box',color:'',url:'https://ustppu.github.io/pkgpuassetbooking/'},{title:'Tempahan Fasiliti',text:'Cari ruang yang sesuai untuk program dan aktiviti anda.',icon:'building',color:'violet',url:'https://ustppu.github.io/pkgpufacilitiesbooking/'},{title:'PU Insight',text:'Terokai analisis dan dapatan pendidikan daerah.',icon:'chart',color:'amber',url:'https://ustppu.github.io/digitalschool/'}];
let participantSearch='';
let route='#/',generation=0,programs=[],detail=null,adminTab='overview',filter='Semua',search='',lastCertificate=null,eventQrKind='registration',schoolFilter='all',schoolSearch='';
let passes=[];try{passes=JSON.parse(localStorage.getItem('pkg-hub-my-passes-v1'))||[];}catch{}
function savePass(r){passes=passes.filter(p=>p.registrationId!==r.registrationId);passes.unshift({registrationId:r.registrationId,accessKey:r.accessKey,name:r.name,title:r.program.title,programId:r.program.id});try{localStorage.setItem('pkg-hub-my-passes-v1',JSON.stringify(passes));}catch{}}
const passRoute=r=>'#/pas/'+encodeURIComponent(r.registrationId)+'/'+encodeURIComponent(r.accessKey);
const linkFor=hash=>api.publicUrl.split('#')[0]+hash;
function qr(value){if(typeof qrcode==='undefined')return '<p>QR belum dimuatkan.</p>';const code=qrcode(0,'M');code.addData(value);code.make();return code.createSvgTag({cellSize:4,margin:12,scalable:true});}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',5000);}
function shell(){const active=route.split('/')[1]||'home';const nav=[['home','Laman utama','#/','home'],['program','Program & acara','#/program','calendar'],['modul','Modul digital','#/modul','grid'],['dapatkan-sijil','Dapatkan sijil','#/dapatkan-sijil','award']];$('#sidebar').innerHTML=`<a href="#/" class="brand"><span class="brand-mark">${icon('book')}</span><span><strong>USTP</strong><small>PPD PETALING UTAMA</small></span></a><div class="nav-label">RUANG ANDA</div>${nav.map(([k,t,h,i])=>`<a href="${h}" class="nav-item ${active===k?'active':''}">${icon(i)}${t}</a>`).join('')}<div class="nav-label">PENGURUSAN</div><a href="#/admin" class="nav-item ${active==='admin'?'active':''}">${icon('shield')}Programme Manager</a><div class="side-foot"><span>PPD Petaling Utama</span><span>V1.0</span></div>`;
 const labels={home:'Laman utama',program:'Program & acara',modul:'Modul digital',pas:'Penyertaan','dapatkan-sijil':'Dapatkan sijil',sijil:'Sahkan sijil',admin:'Programme Manager'};
 $('#topbar').innerHTML=`<div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="Buka navigasi">${icon('menu')}</button>${icon('home','small')}<span>USTP Digital Hub</span><span>/</span><strong>${labels[active]||'Laman utama'}</strong></div><div class="top-right"><span class="preview-pill">${api.isDemo?'PREVIEW · DATA REKAAN':api.isLive?'PROGRAMME MANAGER':'STAGING · DATA REKAAN'}</span><span class="date-top">${new Date().toLocaleDateString('ms-MY',{day:'numeric',month:'short',year:'numeric'})}</span><button class="avatar" data-action="account" aria-label="Ruang pentadbir">${api.isAdmin?'AD':icon('users','small')}</button></div>`;
 document.querySelector('footer').innerHTML='USTP PPD Petaling Utama <span>•</span> <a href="#/sijil">Sahkan sijil</a>';
 $('#mobile-nav').innerHTML=[['home','Utama','#/','home'],['program','Program','#/program','calendar'],['dapatkan-sijil','Sijil','#/dapatkan-sijil','award'],['admin','Admin','#/admin','shield']].map(([k,t,h,i])=>`<a href="${h}" class="mobile-nav-link ${active===k?'active':''}">${icon(i)}${t}</a>`).join('');
}
function go(hash){document.body.classList.remove('menu-open');if(api.embedded){google.script.history.push({}, {},hash.slice(1));render(hash);}else if(location.hash===hash)render(hash);else location.hash=hash;}
function dateBox(p){return `<div class="date-box"><strong>${esc(p.date.slice(8))}</strong><span>${esc(shortDate(p.date).replace(/^\d+\s*/,''))}</span></div>`;}
function moduleCards(){return modules.map(m=>`<a class="module-card" href="${m.url}" target="_blank" rel="noopener"><div class="module-top"><span class="module-icon ${m.color}">${icon(m.icon)}</span>${icon('external','small')}</div><h3>${m.title}</h3><p>${m.text}</p><div class="module-bottom"><span class="live-dot">Modul sedia ada</span><span>Buka modul ${icon('arrow','small')}</span></div></a>`).join('');}
function programRow(p){return `<a class="program-row" href="#/program/${encodeURIComponent(p.id)}">${dateBox(p)}<div class="grow"><span class="pill ${p.accent==='violet'?'violet':p.accent==='amber'?'amber':''}">${esc(p.category)}</span><h3>${esc(p.title)}</h3><div class="meta">${icon('pin')} ${esc(p.venue)} <span>·</span> ${esc(p.start)}–${esc(p.end)}</div></div>${icon('chevron','small')}</a>`;}
function ratingView(p){return p.feedbackCount>0?`<div class="event-rating"><span aria-label="${p.averageRating} daripada 5 bintang">★ ${Number(p.averageRating).toFixed(1)}/5</span><small>· ${p.feedbackCount} maklum balas</small></div>`:'';}
function eventAction(p){return p.certificatesPublished?`<a class="btn primary" href="${certificateRoute(p)}">${icon('award')} Dapatkan sijil ${icon('arrow','small')}</a>`:`<a class="btn" href="#/program/${encodeURIComponent(p.id)}">Maklumat acara ${icon('arrow','small')}</a>`;}
function programCard(p){return `<article class="program-card" data-program-card data-search="${esc((p.title+' '+p.venue).toLowerCase())}" data-category="${esc(p.category)}"><a class="program-cover ${esc(p.accent||'')}" href="#/program/${encodeURIComponent(p.id)}"><span class="cover-icon">${icon('book')}</span><span class="cover-label">USTP PPD PETALING UTAMA · PROGRAM</span></a><div class="program-body">${status(p)}<h3><a href="#/program/${encodeURIComponent(p.id)}">${esc(p.title)}</a></h3><div class="meta-stack"><div>${icon('calendar')}${fullDate(p.date)} · ${esc(p.start)}–${esc(p.end)}</div><div>${icon('pin')}${esc(p.venue)}</div></div>${ratingView(p)}<div class="program-card-bottom">${eventAction(p)}</div></div></article>`;}

function certificateSteps(p={feedbackRequired:true}){return `<ol class="certificate-steps"><li><span>1</span><div><strong>Cari nama / emel</strong><small>Pilih rekod penyertaan anda</small></div></li><li><span>2</span><div><strong>${p.feedbackRequired?'Isi maklum balas':'Maklum balas (pilihan)'}</strong><small>Cukup sekali untuk acara ini</small></div></li><li><span>3</span><div><strong>Jana & muat turun sijil</strong><small>Boleh dibuka semula kemudian</small></div></li></ol>`;}
function certificateEventCard(p){return `<article class="certificate-event-card"><div class="event-card-art">${icon('calendar')}<span>USTP · PROGRAM & ACARA</span></div><div class="event-card-content">${status(p)}<h3>${esc(p.title)}</h3><div class="meta-stack"><div>${icon('calendar')}${fullDate(p.date)} · ${esc(p.start)}–${esc(p.end)}</div><div>${icon('pin')}${esc(p.venue)}</div></div>${ratingView(p)}<div class="actions mt">${eventAction(p)}</div>${p.certificatesPublished?'<p class="dialog-note mt">Lengkapkan maklum balas untuk mendapatkan sijil. Sudah lengkap? Terus jana semula.</p>':''}</div></article>`;}

function certificateCatalogue(){const events=USTPEvents.ordered(programs).filter(p=>p.certificatesPublished);return `<div class="page-heading"><div><div class="eyebrow">UNTUK PESERTA PROGRAM</div><h1>Dapatkan sijil program</h1><p>Pilih acara yang anda hadiri. Cari nama, lengkapkan maklum balas dan muat turun sijil.</p></div></div>${certificateSteps()}<div class="certificate-events-grid mt">${events.map(certificateEventCard).join('')||empty('calendar','Belum ada acara untuk sijil','Acara yang sedang berlangsung atau sudah selesai akan dipaparkan di sini.')}</div><p class="dialog-note mt">Sudah lengkap maklum balas? Buka semula acara dan cari nama untuk mendapatkan sijil tanpa mengisi semula.</p><a href="#/program" class="text-link mt">Lihat semua program ${icon('arrow','small')}</a>`;}
function home(){const recent=USTPEvents.homepage(programs),upcoming=USTPEvents.ordered(programs).filter(p=>eventPhase(p)==='upcoming').slice(0,3);return `<div class="page-heading hub-home-heading"><div><div class="eyebrow">USTP PPD PETALING UTAMA</div><h1>Ruang digital.<br><span>Ilmu, pengalaman & hubungan.</span></h1><p>Terokai acara, urus keperluan dan dapatkan sijil penyertaan anda.</p></div><div class="home-emblem" aria-hidden="true">${icon('book')}</div></div>${recent.length?`<div class="section-head"><div><h2>Sedang berlangsung & baru selesai</h2><p>Acara terkini untuk komuniti pendidikan Petaling Utama.</p></div><a href="#/program" class="text-link">Semua acara ${icon('arrow','small')}</a></div><div class="certificate-events-grid">${recent.map(certificateEventCard).join('')}</div>`:''}${upcoming.length?`<div class="section-head"><div><h2>Program akan datang</h2><p>Rancang penyertaan anda.</p></div><a href="#/program" class="text-link">Semua program</a></div><div class="program-list">${upcoming.map(programRow).join('')}</div>`:''}<div class="section-head"><div><h2>Perkhidmatan digital</h2><p>Akses terus ke modul anda.</p></div></div><div class="modules-grid">${moduleCards()}</div>`;}

function certificateEntry(p){if(!p.certificatesPublished)return empty('clock','Sijil belum diterbitkan','Penganjur akan membuka maklum balas dan sijil selepas penerbitan.');return `<a class="back-link" href="#/dapatkan-sijil">${icon('back','small')} Semua acara & sijil</a><div class="certificate-entry-header">${status(p)}<h1>Maklum balas & sijil</h1><h2>${esc(p.title)}</h2><p>${fullDate(p.date)} · ${esc(p.venue)}</p></div>${certificateSteps(p)}${certificateSearchView(p)}<p class="dialog-note mt">${p.feedbackRequired?'Maklum balas wajib dilengkapkan sebelum sijil boleh dijana. ':''}Jika sudah lengkap, anda boleh terus jana atau muat turun semula sijil. Sijil dibuka selepas diterbitkan oleh penganjur.</p>`;}
function empty(i,title,body,action=''){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${body}</p>${action}</div>`;}
function catalogue(){return `<div class="page-heading"><div><div class="eyebrow">BELAJAR & BERHUBUNG</div><h1>Program & acara</h1><p>Pilih acara untuk maklumat program, maklum balas dan carian sijil.</p></div></div><div class="filters"><div class="chip-row">${['Semua','Bengkel','Latihan','Perkongsian','Taklimat'].map(x=>`<button class="chip ${filter===x?'active':''}" data-action="filter" data-value="${x}">${x}</button>`).join('')}</div><div class="search-field">${icon('search')}<input id="program-search" aria-label="Cari program" placeholder="Cari program atau lokasi…" value="${esc(search)}"></div></div><div class="program-grid">${USTPEvents.ordered(programs).map(programCard).join('')}</div><div id="no-filter" hidden>${empty('search','Tiada program sepadan','Cuba kategori atau carian lain.')}</div>`;}
function programDetailContent(p){return `<a class="back-link" href="#/program">${icon('back','small')} Semua program</a><section class="detail-banner"><div><span class="pill ${esc(p.accent||'')}">${esc(p.category)}</span><h1>${esc(p.title)}</h1></div><span class="big-icon">${icon('book')}</span></section><div class="detail-grid"><div class="panel"><h2>Tentang program</h2><p class="prose mt">${esc(p.description)}</p><div class="subtle-divider"></div><h3>Perjalanan penyertaan anda</h3><ol class="steps"><li class="step" data-n="1">Imbas QR acara</li><li class="step" data-n="2">Daftar / rekod hadir</li><li class="step" data-n="3">Beri maklum balas</li><li class="step" data-n="4">Dapatkan sijil</li></ol><p class="muted" style="font-size:11px">${p.feedbackRequired?'Maklum balas diperlukan untuk melayakkan sijil.':'Maklum balas digalakkan untuk membantu penambahbaikan program.'} Sijil tersedia selepas diterbitkan penganjur.</p></div><aside class="panel detail-side">${status(p)}<div class="meta-stack mt"><div>${icon('calendar')}${fullDate(p.date)}</div><div>${icon('clock')}${esc(p.start)} – ${esc(p.end)}</div><div>${icon('pin')}${esc(p.venue)}</div><div>${icon('users')}${esc(p.organizer)}</div></div><div class="subtle-divider"></div><div style="display:flex;justify-content:space-between;font-size:11px"><span class="muted">Tempat diisi</span><strong>${p.registered} / ${p.capacity}</strong></div><div class="capacity"><span style="width:${Math.min(100,p.registered/p.capacity*100)}%"></span></div><button class="btn primary" data-action="register" data-id="${esc(p.id)}" ${p.checkInOpen===false||p.eventMode==='onsite'||p.status!=='published'||p.registrationCloses<malaysiaToday()||p.registered>=p.capacity?'disabled':''}>${p.checkInOpen===false?'Kehadiran ditutup':p.eventMode==='onsite'?'Imbas QR acara untuk daftar':'Daftar penyertaan'} ${icon('arrow','small')}</button><small class="muted" style="display:block;text-align:center;margin-top:12px">Tutup pendaftaran: ${fullDate(p.registrationCloses)}</small></aside></div>`;}
function programDetail(p){if(!p.certificatesPublished)return programDetailContent(p);return `<div class="event-certificate-banner"><div><strong>Sudah hadir acara ini?</strong><p>Cari rekod anda, isi maklum balas dan dapatkan sijil.</p></div><a class="btn primary" href="${certificateRoute(p)}">${icon('award')} Dapatkan sijil ${icon('arrow','small')}</a></div>`+programDetailContent(p)+certificateSearchView(p);}
function certificateSearchView(p){return `<section class="panel mt" id="certificate-search-panel"><h2>Cari rekod penyertaan anda</h2><p class="dialog-note mt">Taip sebahagian nama atau emel yang digunakan semasa mendaftar. Pilih nama dan sekolah anda dalam hasil carian acara ini.</p><div class="search-field mt">${icon('search')}<input id="certificate-search" data-program="${esc(p.id)}" type="search" autocomplete="off" maxlength="254" aria-label="Cari peserta acara menggunakan nama atau emel" aria-describedby="certificate-search-hint" placeholder="Nama atau emel anda…"></div><p id="certificate-search-hint" class="dialog-note mt">Taip sekurang-kurangnya 3 huruf. Nama dan sekolah akan muncul secara automatik.</p><div id="certificate-search-results" aria-live="polite"></div></section>`;}
let lookupTimer,lookupVersion=0,lookupRunning=false;
async function searchCertificates(){
 const input=$('#certificate-search');if(!input)return;const query=input.value.trim(),programId=input.dataset.program,version=lookupVersion,target=$('#certificate-search-results');
 if(query.length<3){target.innerHTML='';return;}if(lookupRunning){lookupTimer=setTimeout(searchCertificates,150);return;}lookupRunning=true;target.innerHTML='<p class="dialog-note mt">Mencari…</p>';
 try{const data=await api.call('public.certificateSearch',{programId,query});if(version!==lookupVersion||input!==$('#certificate-search'))return;
 target.innerHTML=data.results.length?data.results.map(r=>{const e=r.eligibility,attrs=`data-id="${esc(r.registrationId)}" data-lookup-key="${esc(r.lookupKey)}" data-program="${esc(programId)}"`,note=r.revoked?'Sijil dibatalkan. Hubungi urus setia.':!e.present?'Kehadiran belum disahkan. Hubungi urus setia.':!e.published?'Maklum balas dan sijil akan dibuka selepas admin menerbitkan sijil.':!r.feedbackDone&&detail.feedbackRequired?'Langkah seterusnya: isi maklum balas untuk membuka sijil.':r.feedbackDone?'Maklum balas sudah lengkap. Sijil boleh dijana atau dimuat turun semula.':'Sijil tersedia.';return `<article class="lookup-result"><div><h3>${esc(r.name)}</h3><p class="muted">${esc(r.school)}</p><p class="dialog-note mt">${note}</p></div><div class="actions">${e.present&&e.published&&!r.feedbackDone?`<button class="btn primary" data-action="lookup-feedback" ${attrs}>Isi maklum balas untuk sijil</button>`:''}${e.eligible&&e.published&&!r.revoked?`<button class="btn primary" data-action="lookup-certificate" ${attrs}>${icon('award')} Jana / muat turun sijil</button>`:''}</div></article>`;}).join('')+(data.more?'<p class="dialog-note mt">Lebih banyak padanan. Taip nama atau emel dengan lebih lengkap.</p>':''):'<p class="dialog-note mt">Tiada peserta sepadan dalam acara ini. Semak ejaan nama atau emel semasa pendaftaran.</p>';
 }catch(e){if(version===lookupVersion&&input===$('#certificate-search'))target.innerHTML=`<p class="form-error mt">${esc(e.message)}</p><button class="btn small" data-action="retry-certificate-search">Cuba semula</button>`;}finally{lookupRunning=false;}
}
function passPage(r,accessKey){const eligible=r.eligibility,certReady=eligible.eligible&&eligible.published;return `<div class="ticket"><div class="page-heading"><div><div class="eyebrow">PENYERTAAN ANDA</div><h1>${eligible.present?'Kehadiran anda direkodkan':'Pendaftaran anda diterima'}</h1><p>Anda juga boleh kembali ke halaman acara dan cari nama atau emel untuk maklum balas serta sijil.</p></div><button class="btn small" data-action="refresh">${icon('clock','small')} Semak status</button></div><ol class="steps"><li class="step done" data-n="1">Pendaftaran</li><li class="step ${eligible.present?'done':''}" data-n="2">Kehadiran</li><li class="step ${r.feedbackDone?'done':''}" data-n="3">Maklum balas</li><li class="step ${r.certificate&&!r.certificate.revoked?'done':''}" data-n="4">Sijil</li></ol><div class="panel"><div class="ticket-body"><div><span class="pill">${esc(r.program.category)}</span><h2 class="ticket-title">${esc(r.program.title)}</h2><div class="meta-stack"><div>${icon('calendar')}${fullDate(r.program.date)} · ${esc(r.program.start)}</div><div>${icon('pin')}${esc(r.program.venue)}</div></div><h3 class="ticket-name">${esc(r.name)}</h3><p class="muted" style="font-size:12px">${esc(r.school)}</p><p class="muted" style="font-size:9px;margin-top:9px">${esc(r.registrationId)}</p></div><div class="participation-receipt">${icon(eligible.present?'check':'ticket')}<strong>${eligible.present?'Kehadiran direkodkan':'Pendaftaran diterima'}</strong><small>${eligible.present?'Terima kasih kerana menyertai acara.':'Imbas QR kehadiran yang dipaparkan penganjur pada hari program.'}</small></div></div><div class="ticket-actions"><div class="actions"><button class="btn" data-action="copy-pass" data-id="${esc(r.registrationId)}" data-key="${esc(accessKey)}">${icon('copy','small')} Salin pautan penyertaan</button>${eligible.present&&eligible.published&&!r.feedbackDone?`<button class="btn primary" data-action="feedback" data-id="${esc(r.registrationId)}" data-key="${esc(accessKey)}">Beri maklum balas ${icon('arrow','small')}</button>`:''}${certReady?`<button class="btn primary" data-action="certificate" data-id="${esc(r.registrationId)}" data-key="${esc(accessKey)}">${icon('award')} Buka sijil</button>`:''}</div><div class="pass-note">${r.certificate?.revoked?'Sijil telah dibatalkan. Hubungi penganjur untuk semakan.':!eligible.present?'Imbas QR kehadiran acara pada hari program. Jika ada masalah, hubungi urus setia.':!eligible.published?'Kehadiran sudah disahkan. Maklum balas dan sijil akan dibuka selepas admin menerbitkan sijil.':!r.feedbackDone&&r.program.feedbackRequired?'Lengkapkan maklum balas sekali untuk mendapatkan sijil.':'Anda layak menerima sijil. Buka sijil untuk mencetak atau menyimpan PDF.'}</div></div></div></div>`;}
function expiredAdminSession(message){api.logout();if($('#modal').open)$('#modal').close();detail=null;$('#main').innerHTML=loginView();shell();const notice=$('#main .form-error');if(notice)notice.textContent='Sesi tamat. Masukkan semula emel admin dan PIN.';else toast(message||'Sila masuk semula sebagai admin.');}
function loginView(){if(api.adminLoginMode==='google')return empty('shield','PIN admin belum diaktifkan','Pemilik cm4 perlu mengaktifkan PIN terlebih dahulu.');return `<div class="panel login-panel"><div class="login-icon">${icon('shield')}</div><div class="eyebrow">RUANG PENTADBIR</div><h1>Programme Manager</h1><p>Masukkan emel admin yang dibenarkan dan PIN untuk meneruskan.</p><form id="admin-login-form"><div class="field"><label for="admin-email">Emel admin</label><input id="admin-email" name="email" type="email" required maxlength="254" autocomplete="username"></div><div class="field mt"><label for="admin-pin">PIN</label><input id="admin-pin" name="pin" type="password" required maxlength="128" autocomplete="current-password"></div><p class="form-error" role="alert"></p><button class="btn primary mt">Masuk Programme Manager ${icon('arrow','small')}</button></form><small>Log masuk Google tidak diperlukan. Akses terhad kepada admin yang dibenarkan.</small></div>`;}
function stat(label,value,ico,foot=''){return `<div class="stat-card"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function adminDashboard(d){return `<div class="sync-status" id="sync-status" role="status">Kemas kini automatik setiap 20 saat</div><div class="page-heading"><div><div class="eyebrow">RUANG KERJA ANDA</div><h1>Programme Manager</h1><p>Dari perancangan pertama hingga sijil terakhir.</p></div><div class="actions"><button class="btn small" data-action="logout">${icon('logout','small')} Keluar</button><button class="btn primary" data-action="new-program">${icon('plus')} Cipta program</button></div></div><div class="stats">${stat('Jumlah program',d.counts.programs,'calendar','Semua program dalam pengurusan')}${stat('Pendaftaran',d.counts.registrations,'users','Peserta berdaftar')}${stat('Kehadiran',d.counts.attendance,'check','Peserta daftar melalui QR acara')}${stat('Sijil diterbitkan',d.counts.certificates,'award','Sijil yang sah')}</div><div class="panel table-panel"><div class="table-panel-head"><div><h2>Program anda</h2><p class="muted" style="font-size:11px;margin-top:4px">Pilih program untuk mengurus peserta dan aktiviti.</p></div><span class="pill gray">${d.programs.length} program</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Program</th><th>Tarikh</th><th>Peserta</th><th>Status</th><th></th></tr></thead><tbody>${d.programs.map(p=>`<tr><td class="title-cell">${esc(p.title)}<small>${esc(p.category)} · ${esc(p.venue)}</small></td><td>${shortDate(p.date)}</td><td>${p.registered} / ${p.capacity}</td><td>${status(p)}</td><td><a href="#/admin/program/${encodeURIComponent(p.id)}" class="btn small">Urus ${icon('arrow','small')}</a></td></tr>`).join('')}</tbody></table></div></div><div class="section-head"><h2>Aktiviti terkini</h2></div><div class="panel">${d.activities.length?d.activities.map(a=>`<div class="activity"><span class="activity-dot"></span><div><p>${esc(activityLabel(a.action))}</p><small>${esc(a.detail)} · ${localTime(a.at)}</small></div></div>`).join(''):'<p class="muted" style="font-size:12px">Aktiviti pengurusan akan direkodkan di sini.</p>'}</div>`;}
function activityLabel(a){return {'participant.updated':'Rekod peserta disunting','attendance.gate':'Status kehadiran ditukar','program.created':'Program baharu dicipta','program.updated':'Maklumat program dikemas kini','attendance.confirmed':'Kehadiran peserta disahkan','certificate.settings.updated':'Tetapan sijil dikemas kini','feedback.reset':'Maklum balas direset','feedback.restored':'Jawapan maklum balas dipulihkan','certificates.published':'Sijil dibuka kepada peserta','certificate.revoked':'Sijil dibatalkan'}[a]||a;}
function adminProgram(d){const p=d.program,r=d.report;let content='';if(adminTab==='overview')content=`<div class="stats">${stat('Pendaftaran',r.registered,'users')}${stat('Hadir',r.attended,'check')}${stat('Maklum balas',r.feedback,'chart')}${stat('Layak sijil',r.eligible,'award')}</div><div class="detail-grid"><div class="panel"><h2>Ringkasan program</h2><p class="prose mt">${esc(p.description)}</p><div class="subtle-divider"></div><div class="meta-stack"><div>${icon('calendar')}${fullDate(p.date)} · ${esc(p.start)} – ${esc(p.end)}</div><div>${icon('pin')}${esc(p.venue)}</div><div>${icon('users')}${esc(p.organizer)}</div></div></div><div class="panel"><h3>Persediaan program</h3><div class="meta-stack mt"><div>${icon('qr')}Peserta imbas QR acara</div><div>${icon('check')}${esc(modeName(p))}</div><div>${icon(p.feedbackRequired?'check':'info')}Maklum balas ${p.feedbackRequired?'diwajibkan':'pilihan'}</div><div>${icon(p.certificatesPublished?'check':'clock')}Sijil ${p.certificatesPublished?'sudah dibuka':'belum diterbitkan'}</div></div><a class="btn mt" href="#/program/${encodeURIComponent(p.id)}">Lihat halaman awam ${icon('external','small')}</a></div></div>`;
 if(adminTab==='eventqr')content=eventQrView(p);
 if(adminTab==='participants')content=`<div class="panel table-panel"><div class="table-panel-head"><h2>Peserta berdaftar</h2><button class="btn small" data-action="export" data-id="${esc(p.id)}">${icon('download','small')} Eksport CSV</button></div>${participantsTable(d)}</div>`;
 if(adminTab==='schools')content=schoolCoverageView(d);
 if(adminTab==='attendance')content=`<div class="callout">Peserta mengimbas QR acara pada telefon sendiri. ${p.eventMode==='onsite'?'Borang acara terus merekod kehadiran.':'Gunakan QR kehadiran berasingan selepas pradaftar.'} <button class="btn small" data-action="admin-tab" data-value="eventqr">Buka QR acara</button></div><div class="panel table-panel"><div class="table-panel-head"><div><h2>Kehadiran peserta</h2><p class="dialog-note mt">Pengesahan manual disediakan untuk urus setia menyelesaikan masalah peserta.</p></div><div class="actions"><span class="pill">${r.attended} / ${r.registered} hadir</span><button class="btn primary small" data-action="attendance-report">${icon('download','small')} Jana PDF laporan kehadiran</button></div></div>${participantsTable(d,true)}</div>`;
 if(adminTab==='feedback')content=`<div class="panel"><div class="feedback-layout"><div><span class="eyebrow">PENILAIAN KESELURUHAN</span><div class="score">${r.average||'—'}<small style="font-size:18px;letter-spacing:0;color:#9caaa8"> / 5</small></div><p class="muted" style="font-size:11px;margin-top:8px">${r.feedback} maklum balas diterima</p></div><div><h2>Suara peserta</h2><div class="actions mt"><button class="btn small" data-action="reset-feedback">Reset maklum balas</button>${p.feedbackLastReset&&!p.feedbackLastReset.restoredAt?'<button class="btn small" data-action="restore-feedback">Pulihkan jawapan sebelum reset</button>':''}</div><p class="muted" style="font-size:11px;margin:8px 0 20px">Nama dan emel tidak dipaparkan bersama komen dalam ringkasan ini.</p>${d.responses.length?d.responses.map(f=>`<div class="response"><span class="pill amber">${'★'.repeat(f.rating)} ${f.rating}/5</span><p>${esc(f.comment||'Tiada ulasan tambahan.')}</p>${f.suggestion?`<p><strong>Cadangan:</strong> ${esc(f.suggestion)}</p>`:''}<small class="muted">${localTime(f.at)}</small></div>`).join(''):empty('chart','Maklum balas belum diterima','Peserta yang hadir boleh mengisi maklum balas melalui carian pada halaman acara.')}</div></div></div>`;
 if(adminTab==='certificates')content=`<div class="panel"><div class="page-heading" style="margin-bottom:0"><div><h2>Sijil penyertaan</h2><button class="btn small mt" data-action="certificate-settings">${icon('edit','small')} Tetapan sijil</button><p>${r.eligible} peserta layak · ${r.certificates} sijil dijana</p></div>${p.certificatesPublished?'<span class="pill">Sijil sudah diterbitkan</span>':`<button class="btn primary" data-action="publish-certs" data-id="${esc(p.id)}">${icon('award')} Terbitkan sijil</button>`}</div><div class="callout mt">Sijil hanya boleh dijana selepas kehadiran disahkan${p.feedbackRequired?' dan maklum balas dilengkapkan':''}. Nama dan butiran pada sijil dibekukan ketika sijil dikeluarkan.</div>${d.participants.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Peserta</th><th>Kelayakan</th><th>Nombor sijil</th><th></th></tr></thead><tbody>${d.participants.map(x=>`<tr><td>${esc(x.name)}<small>${esc(x.school)}</small></td><td><span class="pill ${x.eligible?'':'gray'}">${x.eligible?'Layak':'Belum lengkap'}</span></td><td>${x.certificate?esc(x.certificate.id)+(x.certificate.revoked?' <span class="pill red">Dibatalkan</span>':''):'<span class="muted">Belum dijana peserta</span>'}</td><td>${x.certificate&&!x.certificate.revoked?`<button class="btn small danger" data-action="revoke" data-id="${esc(x.certificate.id)}">Batalkan</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`;
 return `<div class="sync-status" id="sync-status" role="status">Kemas kini automatik setiap 20 saat</div><a href="#/admin" class="back-link">${icon('back','small')} Semua program</a><div class="page-heading"><div><div class="eyebrow">PENGURUSAN PROGRAM</div><h1 style="font-size:27px;max-width:730px">${esc(p.title)}</h1><p>${fullDate(p.date)} · ${esc(p.venue)}</p></div><button class="btn" data-action="edit-program">${icon('edit','small')} Sunting</button></div><section class="event-control-bar"><div><span class="eyebrow">KEHADIRAN</span><button class="attendance-toggle ${p.checkInOpen!==false&&p.status==='published'?'is-open':''}" role="switch" aria-checked="${p.checkInOpen!==false&&p.status==='published'}" aria-label="Buka atau tutup kehadiran" data-action="toggle-attendance" ${p.status==='draft'?'disabled':''}><span class="toggle-track"><span></span></span><strong>${p.checkInOpen!==false&&p.status==='published'?'Buka':'Tutup'}</strong></button></div><div class="certificate-control"><span class="eyebrow">SIJIL PESERTA</span>${p.certificatesPublished?'<span class="pill">Sudah diterbitkan</span>':`<button class="btn primary" data-action="publish-certs" data-id="${esc(p.id)}">${icon('award')} Terbitkan sijil</button>`}<button class="btn small" data-action="certificate-settings">${icon('edit','small')} Tetapan sijil</button></div></section><div class="tabs">${[['overview','Ringkasan'],['eventqr','QR acara'],['participants','Peserta'],['schools','Sekolah'],['attendance','Kehadiran'],['feedback','Maklum balas'],['certificates','Sijil']].map(([k,t])=>`<button class="tab ${adminTab===k?'active':''}" data-action="admin-tab" data-value="${k}">${t}</button>`).join('')}</div>${content}`;
}
function schoolCoverageRows(d){return d.schools.filter(s=>(schoolFilter==='all'||(schoolFilter==='registered'?s.registered>0:s.registered===0))&&(s.name+' '+s.code).toLowerCase().includes(schoolSearch.toLowerCase())).map(s=>`<tr><td>${esc(s.name)}<small>${esc(s.code)}</small></td><td><span class="pill ${s.registered?'':'gray'}">${s.registered?'Sudah daftar':'Belum daftar'}</span></td><td>${s.registered}</td><td>${s.attended}</td></tr>`).join('')||'<tr><td colspan="4">Tiada sekolah sepadan.</td></tr>';}
function updateSchoolRows(){if($('#school-coverage-body'))$('#school-coverage-body').innerHTML=schoolCoverageRows(detail);document.querySelectorAll('[data-action=school-filter]').forEach(x=>x.classList.toggle('active',x.dataset.value===schoolFilter));}
function schoolCoverageView(d){const r=d.schoolSummary;return `<div class="stats">${stat('Sekolah dalam senarai',r.total,'building')}${stat('Sekolah sudah daftar',r.registered,'check')}${stat('Sekolah belum daftar',r.notRegistered,'clock')}${stat('Rekod perlu semak',r.needsReview,'info')}</div><div class="callout">Sasaran acara: ${d.program.targetAudience==='primary'?'SR sahaja':d.program.targetAudience==='secondary'?'SM sahaja':'SR & SM'} · ${r.total} sekolah dalam senarai rujukan PU Insight. ${r.needsReview?'Masih ada '+r.needsReview+' rekod sekolah / organisasi yang belum dipadankan. Semak rekod ini sebelum menghubungi sekolah yang ditanda belum daftar.':'Nama sekolah asal dikekalkan dalam rekod.'}${r.outsideTarget?' Terdapat '+r.outsideTarget+' rekod di luar sasaran semasa; rekod ini dikekalkan dan tidak dikira dalam liputan sekolah sasaran.':''}</div><section class="panel table-panel"><div class="table-panel-head"><h2>Penyertaan mengikut sekolah</h2></div><div class="filters" style="padding:16px"><div class="chip-row">${[['all','Semua'],['registered','Sudah daftar'],['missing','Belum daftar']].map(([v,t])=>`<button class="chip ${schoolFilter===v?'active':''}" data-action="school-filter" data-value="${v}">${t}</button>`).join('')}</div><div class="search-field">${icon('search')}<input id="school-progress-search" value="${esc(schoolSearch)}" placeholder="Cari nama atau kod sekolah" aria-label="Cari sekolah dalam dashboard"></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Sekolah</th><th>Status</th><th>Peserta</th><th>Hadir</th></tr></thead><tbody id="school-coverage-body">${schoolCoverageRows(d)}</tbody></table></div></section>${r.needsReview?`<section class="panel table-panel mt"><div class="table-panel-head"><h2>Nama sekolah perlu disemak</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Peserta</th><th>Nama sekolah / organisasi asal</th></tr></thead><tbody>${d.participants.filter(r=>r.schoolNeedsReview).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.schoolOriginal)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function participationLabel(r){return r.participationType==='representative'?'Wakil':r.participationType==='participant'?'Peserta':'Belum dinyatakan';}
function participantRows(d,attendance){const rows=d.participants.filter(r=>(r.name+' '+r.email+' '+r.school).toLowerCase().includes(participantSearch.toLowerCase()));return rows.map(r=>`<tr><td data-label="Peserta"><strong>${esc(r.name)}</strong><small>${esc(r.email)}</small></td><td data-label="Sekolah">${esc(r.school)}</td><td data-label="Peranan">${participationLabel(r)}<small>${esc(r.position||'Jawatan belum dinyatakan')}</small></td><td data-label="Kehadiran"><span class="pill ${r.attendance?'':'gray'}">${r.attendance?'Hadir':'Berdaftar'}</span>${attendance&&r.attendance?`<small>${localTime(r.attendance.at)}</small>`:''}</td><td data-label="Tindakan"><div class="actions"><button class="btn small" data-action="edit-participant" data-id="${esc(r.id)}">Sunting</button>${attendance&&!r.attendance?`<button class="btn small" data-action="manual-attend" data-id="${esc(r.id)}">Sahkan hadir</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="5">Tiada rekod sepadan.</td></tr>';}
function participantsTable(d,attendance=false){if(!d.participants.length)return empty('users','Belum ada peserta','Pendaftaran akan muncul di sini.');return `<div class="participant-tools"><div class="search-field">${icon('search')}<input id="participant-search" data-attendance="${attendance}" value="${esc(participantSearch)}" placeholder="Cari nama, emel atau sekolah" aria-label="Cari peserta"></div></div><div class="table-wrap"><table class="data-table participant-table"><thead><tr><th>Peserta</th><th>Sekolah / Organisasi</th><th>Peserta / Wakil</th><th>Status</th><th>Tindakan</th></tr></thead><tbody id="participant-rows">${participantRows(d,attendance)}</tbody></table></div>`;}
function schoolField(p,r={}){return `<div class="field full"><label for="f-school">Sekolah / Organisasi</label><input id="f-school" name="school" list="school-directory" required maxlength="180" autocomplete="off" value="${esc(r.school||'')}" placeholder="Cari dan pilih nama sekolah rasmi"><datalist id="school-directory">${USTPSchools.forAudience(p.targetAudience||'both').map(x=>`<option value="${esc(x.name)}">${esc(x.code)}</option>`).join('')}</datalist>${p.allowExternal?`<label class="check-field mt"><input type="checkbox" name="schoolOther" ${r.external?'checked':''}><span>Peserta luar PU / organisasi lain</span></label>`:''}<small class="dialog-note">${p.allowExternal?'Acara terbuka: peserta luar PU boleh isi nama sekolah / organisasi sendiri.':'Pilih nama sekolah rasmi dalam senarai PU.'}</small></div>`;}
function roleFields(r={},required=true){return `<div class="field"><label for="f-participationType">Penyertaan sebagai</label><select id="f-participationType" name="participationType" ${required?'required':''}><option value="">${required?'Pilih Peserta / Wakil':'Belum dinyatakan'}</option><option value="participant" ${r.participationType==='participant'?'selected':''}>Peserta</option><option value="representative" ${r.participationType==='representative'?'selected':''}>Wakil</option></select></div>${field('Jawatan','position',r.position||'','text',(required?'required ':'')+'maxlength="150" placeholder="Contoh: Pengetua, Guru Besar, Guru"')}`;}
async function editParticipant(id){const r=detail.participants.find(x=>x.id===id);if(!r)throw Error('Peserta tidak ditemui.');const h=await api.call('admin.participantHistory',{programId:detail.program.id,registrationId:id});modal('Sunting rekod peserta',`<form id="participant-form" data-id="${esc(id)}"><div class="form-grid">${field('Nama penuh untuk sijil','name',r.name,'text','required maxlength="150"')}${schoolField(detail.program,r)}${roleFields(r,false)}</div><p class="dialog-note mt">Emel, kehadiran dan maklum balas dikekalkan. Sijil yang sudah dijana mengekalkan butiran asalnya.</p><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Batal</button><button class="btn primary">Simpan perubahan</button></div></form><details class="participant-history mt"><summary>Sejarah perubahan (${h.history.length})</summary>${h.history.map(x=>`<article class="response"><strong>${localTime(x.at)}</strong><small>${esc(x.actor)}</small>${[['name','Nama'],['school','Sekolah'],['participationType','Peserta / Wakil'],['position','Jawatan']].filter(([k])=>x.before?.[k]!==x.after?.[k]).map(([k,t])=>`<p>${t}: ${esc(k==='participationType'?participationLabel({participationType:x.before?.[k]}):x.before?.[k]||'—')} → ${esc(k==='participationType'?participationLabel({participationType:x.after?.[k]}):x.after?.[k]||'—')}</p>`).join('')}</article>`).join('')||'<p>Belum ada perubahan.</p>'}</details>`,true);}

function verifyView(){return `<div class="page-heading"><div><div class="eyebrow">KEPERCAYAAN & PENGESAHAN</div><h1>Semak sijil</h1><p>Sahkan nombor rujukan pada sijil penyertaan USTP Digital Hub.</p></div></div><div class="panel" style="max-width:680px"><form id="verify-form"><div class="field"><label for="cert-id">Nombor sijil</label><input id="cert-id" name="id" required placeholder="Contoh: USTP-2026-…" autocomplete="off"></div><button class="btn primary mt">${icon('shield','small')} Semak kesahihan</button></form><div id="verify-result"></div></div>`;}
function modal(title,body,wide=false){const m=$('#modal');m.className=wide?'wide':'';m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Tutup">${icon('close')}</button></div><div class="modal-content">${body}</div>`;if(!m.open)m.showModal();}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function registrationForm(id){go('#/daftar/'+encodeURIComponent(id));}
const modeName=p=>p.eventMode==='onsite'?'Daftar terus hadir':'Pradaftar + kehadiran berasingan';
function eventLink(p,kind='registration',key=p.eventKey||''){return linkFor('#/'+(kind==='attendance'?'hadir':'daftar')+'/'+encodeURIComponent(p.id)+((kind==='attendance'||p.eventMode==='onsite')?'/'+encodeURIComponent(key):''));}
function eventQrView(p){if(p.status==='draft')return `<div class="panel">${empty('qr','QR menunggu acara diterbitkan','Lengkapkan acara dan pilih status Diterbitkan untuk membuka borang peserta.','<button class="btn primary" data-action="edit-program">Sunting & terbitkan acara</button>')}</div>`;const kind=p.eventMode==='onsite'?'registration':eventQrKind,url=eventLink(p,kind);return `<div class="event-qr-grid"><section class="panel event-qr-card"><div class="eyebrow">PESERTA IMBAS QR INI</div><h2>${kind==='attendance'?'QR kehadiran':'QR acara'}</h2><p class="muted mt">${p.eventMode==='onsite'?'Peserta imbas, isi borang dan terus direkodkan hadir.':kind==='attendance'?'Paparkan pada hari program untuk peserta merekod kehadiran sendiri.':'Kongsi untuk pendaftaran awal. Kehadiran belum dikira.'}</p><div class="event-qr">${qr(url)}</div><strong>${esc(p.title)}</strong><p class="muted" style="font-size:11px;margin-top:6px">${fullDate(p.date)} · ${esc(p.venue)}</p><div class="actions mt" style="justify-content:center"><button class="btn primary" data-action="show-event-qr" data-id="${esc(p.id)}" data-key="${esc(p.eventKey||'')}" data-kind="${kind}">${icon('qr')} Paparkan QR acara</button><button class="btn" data-action="download-event-qr" data-id="${esc(p.id)}" data-kind="${kind}">${icon('download')} Muat turun QR</button></div></section><section class="panel"><span class="pill">${esc(modeName(p))}</span><h3 class="mt">Satu acara, aliran pilihan anda</h3>${p.eventMode!=='onsite'?`<div class="actions mt"><button class="btn ${kind==='registration'?'primary':''}" data-action="event-qr-kind" data-value="registration">QR pradaftar</button><button class="btn ${kind==='attendance'?'primary':''}" data-action="event-qr-kind" data-value="attendance">QR kehadiran</button></div>`:''}<ol class="event-flow"><li>Admin sediakan dan terbitkan acara.</li><li>Admin paparkan atau kongsi QR acara.</li><li>Peserta imbas menggunakan telefon sendiri.</li><li>${p.eventMode==='onsite'?'Peserta isi borang; pendaftaran dan kehadiran disimpan serentak.':'Peserta pradaftar; kemudian imbas QR kehadiran pada hari program.'}</li><li>Maklum balas dan sijil dibuka mengikut syarat acara.</li></ol><label class="field"><span>Pautan borang peserta</span><input class="link-input" readonly value="${esc(url)}"></label><div class="actions mt"><button class="btn" data-action="copy-event-link" data-id="${esc(p.id)}" data-kind="${kind}">${icon('copy')} Salin pautan</button><a class="btn" href="${esc(url.slice(url.indexOf('#')))}">Cuba borang peserta ${icon('arrow','small')}</a></div><p class="dialog-note mt">Status borang kehadiran: <strong>${p.checkInOpen!==false?'Dibuka oleh admin':'Ditutup oleh admin'}</strong>. Tukar mod atau tutup borang melalui Sunting.</p></section></div>`;}
function eventPoster(p,kind,key){const url=eventLink(p,kind,key);return `<div class="poster-toolbar actions"><a class="btn" href="#/admin/program/${encodeURIComponent(p.id)}">${icon('back','small')} Kembali</a><button class="btn" data-action="fullscreen">Skrin penuh</button><button class="btn" data-action="print-event">Cetak / Simpan PDF</button></div><section class="event-poster"><div class="eyebrow">USTP PPD PETALING UTAMA · ${api.isDemo?'PRATONTON DATA REKAAN':api.isLive?'KEHADIRAN PROGRAM':'STAGING DATA REKAAN'}</div><h1>${esc(p.title)}</h1><p class="poster-meta">${fullDate(p.date)} · ${esc(p.start)}–${esc(p.end)}<br>${esc(p.venue)}</p><div class="event-qr">${qr(url)}</div><div class="qr-program-caption"><strong>${esc(p.title)}</strong><span>${fullDate(p.date)} · ${esc(p.start)}–${esc(p.end)}</span></div><h2>Imbas untuk ${kind==='attendance'?'rekod kehadiran':p.eventMode==='onsite'?'daftar & hadir':'pradaftar'}</h2><p>Gunakan kamera telefon anda dan buka pautan borang.</p><span class="pill mt">${esc(modeName(p))}</span></section>`;}
function eventRegistration(p,eventKey='',entry='registration'){const onsite=p.eventMode==='onsite'||entry==='checkin',saved=passes.filter(r=>r.programId===p.id||(!r.programId&&r.title===p.title));return `<div class="event-entry-head"><span class="pill">${esc(modeName(p))}</span><h1>${onsite?'Daftar kehadiran':'Daftar penyertaan'}</h1><h2>${esc(p.title)}</h2><p>${fullDate(p.date)} · ${esc(p.start)}–${esc(p.end)}<br>${esc(p.venue)}</p></div>${api.isDemo?'<div class="callout">Pratonton rekaan: rekod contoh disimpan pada pelayar ini sahaja.</div>':''}${entry==='checkin'&&saved.length?`<section class="panel entry-form"><h3>Sudah pradaftar pada peranti ini?</h3><p class="dialog-note mt">Pilih penyertaan anda untuk mengesahkan kehadiran.</p>${saved.map(r=>`<button class="btn primary mt" data-action="self-checkin" data-id="${esc(r.registrationId)}" data-key="${esc(r.accessKey)}" data-event-key="${esc(eventKey)}" data-program="${esc(p.id)}">Saya ${esc(r.name)} — sahkan hadir</button>`).join('')}</section>`:''}<section class="panel entry-form"><h3>${entry==='checkin'?'Belum pradaftar? Daftar di sini':'Maklumat peserta'}</h3><p class="dialog-note mt">${onsite?'Hantar borang ini untuk menyimpan pendaftaran dan kehadiran serentak.':'Pendaftaran awal sahaja. Kehadiran direkod melalui QR berasingan pada hari program.'}</p><form id="registration-form" data-id="${esc(p.id)}" data-event-key="${esc(eventKey)}" data-entry="${entry}"><div class="form-grid">${field('Nama penuh untuk sijil','name','','text','required maxlength="150" autocomplete="name"')}${field('Emel','email','','email','required maxlength="254" autocomplete="email"')}${schoolField(p)}${roleFields()}<label class="check-field field full"><input name="consent" type="checkbox" required><span>Saya bersetuju maklumat digunakan untuk pengurusan program dan pengesahan sijil.</span></label></div><p class="form-error" role="alert"></p><div class="form-actions"><button class="btn primary">${onsite?'Daftar & rekod hadir':'Daftar penyertaan'} ${icon('arrow','small')}</button></div></form>${entry==='checkin'?'<p class="dialog-note mt">Jika pernah mendaftar pada peranti lain, buka pautan penyertaan yang disimpan pada peranti ini sebelum imbas semula QR kehadiran. Hubungi urus setia jika pautan hilang.</p>':''}</section>`;}
function programForm(p={}){const date=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kuala_Lumpur'});modal(p.id?'Sunting program':'Cipta program baharu',`<form id="program-form" data-id="${esc(p.id||'')}"><div class="form-grid"><div class="field full"><label for="f-title">Nama program</label><input id="f-title" name="title" required maxlength="180" value="${esc(p.title||'')}" placeholder="Nama yang jelas dan mudah dikenali"></div><div class="field"><label for="f-category">Kategori</label><select id="f-category" name="category">${['Bengkel','Latihan','Perkongsian','Taklimat'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div>${field('Tarikh program','date',p.date||date,'date','required')}${field('Masa mula','start',p.start||'09:00','time','required')}${field('Masa tamat','end',p.end||'13:00','time','required')}${field('Lokasi','venue',p.venue||'','text','required maxlength="250"')}${field('Kapasiti peserta','capacity',p.capacity||40,'number','required min="1" max="5000"')}${field('Penganjur','organizer',p.organizer||'USTP PPD Petaling Utama','text','required')}${field('Tutup pradaftar (mod pradaftar)','registrationCloses',p.registrationCloses||p.date||date,'date','required')}<div class="field full"><label for="f-description">Tentang program</label><textarea id="f-description" name="description" required maxlength="4000" rows="4">${esc(p.description||'')}</textarea></div><div class="field full"><label for="f-targetAudience">Sasaran sekolah</label><select id="f-targetAudience" name="targetAudience"><option value="both" ${!p.targetAudience||p.targetAudience==='both'?'selected':''}>SR &amp; SM</option><option value="primary" ${p.targetAudience==='primary'?'selected':''}>SR sahaja</option><option value="secondary" ${p.targetAudience==='secondary'?'selected':''}>SM sahaja</option></select><small class="dialog-note">SR: SK, SJKC dan SJKT. SM termasuk dua Kolej Tingkatan Enam dalam senarai rujukan.</small></div><label class="check-field field full"><input type="checkbox" name="allowExternal" ${p.allowExternal?'checked':''}><span>Kategori terbuka — benarkan peserta luar PU / organisasi lain</span></label><div class="field full"><label for="f-eventMode">Mod pendaftaran & kehadiran</label><select id="f-eventMode" name="eventMode"><option value="onsite" ${p.eventMode!=='preregister'?'selected':''}>Daftar terus hadir — peserta imbas satu QR acara</option><option value="preregister" ${p.eventMode==='preregister'?'selected':''}>Pradaftar dahulu — QR kehadiran berasingan pada hari program</option></select></div><label class="check-field field full"><input type="checkbox" name="checkInOpen" ${p.checkInOpen!==false?'checked':''}><span>Buka borang kehadiran kepada pemegang QR acara. Nyahpilih untuk menutupnya.</span></label><div class="field"><label for="f-status">Status</label><select id="f-status" name="status">${[['draft','Draf'],['published','Diterbitkan'],['closed','Ditutup / Selesai']].map(([v,t])=>`<option value="${v}" ${p.status===v?'selected':''}>${t}</option>`).join('')}</select></div><label class="check-field" style="align-self:center"><input type="checkbox" name="feedbackRequired" ${p.feedbackRequired!==false?'checked':''}><span>Wajib maklum balas sebelum sijil</span></label></div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Batal</button><button class="btn primary">Simpan program ${icon('check','small')}</button></div></form>`,true);}
function feedbackForm(id,key,lookupKey='',programId=''){modal('Suara anda membantu kami',`<p class="dialog-note">Kongsikan pengalaman program. Satu maklum balas bagi setiap penyertaan.</p><form id="feedback-form" data-id="${esc(id)}" data-key="${esc(key)}" data-lookup-key="${esc(lookupKey)}" data-program="${esc(programId)}"><div class="field"><label>Bagaimana pengalaman keseluruhan anda?</label><div class="rating">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" required aria-label="${n} daripada 5"><span>${n} ★</span></label>`).join('')}</div></div><div class="field mt"><label for="feedback-comment">Apa yang paling membantu anda?</label><textarea id="feedback-comment" name="comment" maxlength="1200" placeholder="Kongsikan pandangan anda…"></textarea></div><div class="field mt"><label for="feedback-suggestion">Cadangan penambahbaikan (pilihan)</label><textarea id="feedback-suggestion" name="suggestion" maxlength="800"></textarea></div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Kembali</button><button class="btn primary">Hantar maklum balas ${icon('arrow','small')}</button></div></form>`);}
function certificateDefaults(p={}){return {style:'classic',heading:'SIJIL PENYERTAAN',introduction:'Dengan sukacitanya diperakui bahawa',participation:'telah menyertai',organizer:p.organizer||'USTP PPD Petaling Utama',signerName:'',signerRole:'',footer:'Terima kasih atas komitmen dan penyertaan.',...(p.certificateSettings||{})};}
function certificateSettingsForm(){const p=detail.program,s=certificateDefaults(p);modal('Tetapan sijil',`<p class="dialog-note">Tetapan untuk acara ini. Sijil yang telah dikeluarkan mengekalkan rekod asal; tetapan baharu digunakan apabila sijil baharu dijana. QR acara dan kehadiran tidak berubah.</p><form id="certificate-settings-form" data-id="${esc(p.id)}"><div class="form-grid mt"><div class="field full"><label for="certificate-style">Gaya sijil</label><select id="certificate-style" name="style"><option value="classic" ${s.style==='classic'?'selected':''}>Klasik</option><option value="modern" ${s.style==='modern'?'selected':''}>Moden</option><option value="template" ${s.style==='template'?'selected':''}>Template sendiri</option></select></div>${USTPCertificateTemplate.panel()}${field('Tajuk sijil','heading',s.heading,'text','required maxlength="100"')}${field('Nama penganjur pada sijil','organizer',s.organizer,'text','required maxlength="250"')}<div class="field full"><label for="cert-introduction">Ayat pengenalan</label><textarea id="cert-introduction" name="introduction" required maxlength="500">${esc(s.introduction)}</textarea></div>${field('Ayat sebelum nama program','participation',s.participation,'text','required maxlength="300"')}${field('Nama penandatangan','signerName',s.signerName,'text','maxlength="150"')}${field('Jawatan penandatangan','signerRole',s.signerRole,'text','maxlength="200"')}<div class="field full"><label for="cert-footer">Teks penghargaan / kaki sijil</label><textarea id="cert-footer" name="footer" maxlength="500">${esc(s.footer)}</textarea></div></div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="preview-certificate-settings">Pratonton</button><button type="button" class="btn" data-action="close-modal">Batal</button><button class="btn primary">Simpan tetapan sijil</button></div></form><div id="certificate-preview" class="mt"></div>`,true);USTPCertificateTemplate.init(s,p.id,api);}
function previewCertificateSettings(){const form=$('#certificate-settings-form');if(!form.reportValidity())return;const settings=Object.fromEntries(new FormData(form)),p=detail.program,values={id:'PRATONTON',name:'NAMA PESERTA',school:'NAMA SEKOLAH',title:p.title,program:p.title,date:fullDate(p.date),programDate:p.date,organizer:settings.organizer,settings};const custom=USTPCertificateTemplate.preview(settings,values);$('#certificate-preview').innerHTML='<p class="dialog-note">Pratonton rekaan sahaja. Tiada sijil diterbitkan atau PDF dijana.</p>'+(custom||certificateHtml(values));}
function certificateHtml(c){const s={...certificateDefaults({organizer:c.organizer}),...(c.settings||{})};if(s.style==='template'){if(!c.templateImage)throw Error('Template sijil belum dimuatkan. Cuba buka semula sijil.');return `<style>@page{size:A4 ${s.templateAspect>=1?'landscape':'portrait'}}@media print{#modal .certificate.certificate-uploaded{width:${s.templateAspect>=1?'297':'210'}mm;height:${s.templateAspect>=1?'210':'297'}mm;min-height:0;padding:0;border:0;outline:0;display:flex;align-items:center;justify-content:center}#modal .certificate-uploaded svg{max-height:100%;max-width:100%;width:100%;height:100%}}</style><section class="certificate certificate-uploaded" id="certificate-sheet">${USTPCertificateTemplate.svg(c.templateImage,s.templateAspect,s.templateLayout,{name:c.name,school:c.school,program:c.title,date:fullDate(c.programDate)})}</section>`;}return `<section class="certificate ${s.style==='modern'?'certificate-modern':''}" id="certificate-sheet"><div class="cert-org">USTP PPD Petaling Utama</div><div class="cert-heading">${esc(s.heading)}</div><p>${esc(s.introduction)}</p><div class="cert-name">${esc(c.name)}</div><p>${esc(c.school)}</p><p style="margin-top:18px">${esc(s.participation)}</p><div class="cert-program">${esc(c.title)}</div><p>pada ${fullDate(c.programDate)}</p><div class="cert-bottom"><div class="cert-sign">${esc(s.footer)}${s.signerName?`<strong class="cert-signer">${esc(s.signerName)}</strong><span>${esc(s.signerRole)}</span>`:''}<strong>${esc(c.organizer)}</strong><span>${esc(c.id)}</span></div><div class="cert-qr">${qr(linkFor('#/sijil/'+encodeURIComponent(c.id)))}<small style="font-size:7px">SEMAK KESAHIHAN</small></div></div></section>`;}
function showCertificate(c){lastCertificate=c;modal('Sijil penyertaan',`${certificateHtml(c)}<div class="actions print-actions mt"><button class="btn primary" data-action="print-certificate">${icon('download','small')} Cetak / Simpan PDF</button><a href="#/sijil/${encodeURIComponent(c.id)}" class="btn" data-action="close-and-route">${icon('shield','small')} Semak sijil</a><small class="muted">Pilih “Save as PDF” dalam pilihan cetakan peranti.</small></div>`,true);}
async function checkCertificate(id){try{const c=await api.call('public.verify',{id}),valid=c.status==='valid';$('#verify-result').innerHTML=`<div class="subtle-divider"></div><div class="verify-result"><span class="status-icon ${valid?'':'bad'}">${icon(valid?'check':'close')}</span><h3>${valid?'Sijil ini sah':'Sijil telah dibatalkan'}</h3><p><strong>${esc(c.name)}</strong><br>${esc(c.title)}<br>${fullDate(c.programDate)}</p><p style="font-size:10px;margin-top:17px">${esc(c.id)}<br>${esc(c.organizer)}</p></div>`;}catch(e){$('#verify-result').innerHTML=`<div class="form-error">${esc(e.message)}</div>`;}}
function applyFilters(){let count=0;document.querySelectorAll('[data-program-card]').forEach(el=>{const show=(filter==='Semua'||el.dataset.category===filter)&&el.dataset.search.includes(search.toLowerCase());el.hidden=!show;if(show)count++;});if($('#no-filter'))$('#no-filter').hidden=count>0;}
async function render(hash){route=hash||'#/';if(api.isGateway&&route!=='#/'&&route!=='#/program'&&route!=='#/modul'&&route!=='#/dapatkan-sijil'){location.replace((route.startsWith('#/admin')?(api.adminUrl||api.backendUrl):api.backendUrl)+route);return;}document.body.classList.toggle('presentation',route.startsWith('#/papar/'));const current=++generation;shell();$('#main').innerHTML='<div class="skeleton"></div><div class="skeleton" style="height:240px"></div>';let html='';try{const parts=route.replace(/^#\/?/,'').split('/').map(decodeURIComponent),section=parts[0];if(!section||section==='program'||section==='modul'||section==='dapatkan-sijil')programs=await api.call('public.catalog');if(current!==generation)return;
 if(!section)html=home();else if(section==='modul')html=`<div class="page-heading"><div><div class="eyebrow">PERKHIDMATAN DIGITAL</div><h1>Keperluan anda, satu ruang.</h1><p>Teruskan menggunakan modul dan fungsi admin sedia ada.</p></div></div><div class="modules-grid">${moduleCards()}</div><div class="callout mt">Setiap modul dibuka pada laman sedia ada. Rekod dan fungsi asal dikekalkan.</div>`;
 else if(section==='dapatkan-sijil')html=certificateCatalogue();else if(section==='program'&&!parts[1])html=catalogue();else if(section==='program'){detail=await api.call('public.program',{id:parts[1]});html=parts[2]==='sijil'?certificateEntry(detail):parts[2]==='rekod'?`<div class="page-heading"><div><h1>Cari rekod pendaftaran</h1><p>${esc(detail.title)}</p></div></div>${certificateSearchView(detail)}`:programDetail(detail);}
 else if(section==='daftar'||section==='hadir'){const check=section==='hadir';detail=await api.call('public.program',{id:parts[1]});if(check||detail.eventMode==='onsite')detail=await api.call('public.eventEntry',{id:parts[1],eventKey:parts[2]||''});html=eventRegistration(detail,parts[2]||'',check?'checkin':'registration');}
 else if(section==='papar'){detail=await api.call('public.program',{id:parts[1]});const kind=parts[2]||'registration';if(kind==='attendance'||detail.eventMode==='onsite')await api.call('public.eventEntry',{id:parts[1],eventKey:parts[3]||''});html=eventPoster(detail,kind,parts[3]||'');}
 else if(section==='pas'&&parts[1]&&parts[2]){const r=await api.call('public.pass',{registrationId:parts[1],accessKey:parts[2]});html=passPage(r,parts[2]);}else if(section==='pas'){go('#/program');return;}
 else if(section==='sijil'){html=verifyView();}
 else if(section==='admin'){if(!api.isAdmin)html=loginView();else if(parts[1]==='program'&&parts[2]){detail=await api.call('admin.program',{id:parts[2]});if(adminTab==='eventqr'&&detail.program.status!=='draft'){const access=await api.call('admin.eventAccess',{id:parts[2]});detail.program.eventKey=access.eventKey;}html=adminProgram(detail);}else{const d=await api.call('admin.dashboard');html=adminDashboard(d);}}
 else html=empty('search','Halaman tidak ditemui','Kembali ke laman utama untuk meneruskan.',`<a class="btn" href="#/">Laman utama</a>`);
 if(current!==generation)return;$('#main').innerHTML=html;shell();if(section==='program'&&!parts[1])applyFilters();if(section==='sijil'&&parts[1]){$('#cert-id').value=parts[1];await checkCertificate(parts[1]);}window.scrollTo({top:0,behavior:'instant'});
 }catch(e){if(current===generation){if(e.requiresLogin&&route.startsWith('#/admin')){expiredAdminSession(e.message);return;}$('#main').innerHTML=empty('info','Belum dapat memuatkan maklumat',esc(e.message),'<button class="btn primary" data-action="refresh">Cuba semula</button>');}}
}
async function confirmAttendance(registrationId,accessKey,method){const p=detail?.program,participant=detail?.participants.find(r=>r.id===registrationId);if(!p||!participant)throw Error('Peserta tidak berdaftar untuk program ini.');modal('Sahkan kehadiran',`<div class="callout">${esc(p.title)}</div><h2>${esc(participant.name)}</h2><p class="muted mt">${esc(participant.school)}</p><p class="muted" style="font-size:11px;margin-top:7px">${esc(participant.email)}</p><div class="form-actions"><button class="btn" data-action="close-modal">Batal</button><button class="btn primary" data-action="commit-attendance" data-id="${esc(registrationId)}" data-key="${esc(accessKey||'')}" data-method="${method}">${icon('check')} Sahkan hadir</button></div>`);}
function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Pautan disalin. Simpan untuk dibuka semula.');}catch{modal('Simpan pautan pas',`<p class="dialog-note">Salin dan simpan pautan ini. Ia memberi akses kepada pas anda.</p><input class="link-input" readonly value="${esc(text)}" onclick="this.select()">`);}}
async function action(el){const a=el.dataset.action,id=el.dataset.id,key=el.dataset.key;switch(a){case'toggle-attendance':{await api.call('admin.setAttendanceOpen',{id:detail.program.id,open:detail.program.checkInOpen===false||detail.program.status!=='published'});await render(route);toast(detail.program.checkInOpen?'Kehadiran dibuka.':'Kehadiran ditutup.');break;}case'edit-participant':await editParticipant(id);break;case'attendance-report':{const fresh=await api.call('admin.program',{id:detail.program.id});const report=await USTPAttendanceReport.generate(fresh);download(report.fileName,report.bytes,'application/pdf');toast('Laporan PDF '+report.pages+' halaman dimuat turun.');break;}case'print-attendance':window.print();break;case'menu':document.body.classList.toggle('menu-open');break;case'account':go('#/admin');break;case'refresh':render(route);break;case'close-modal':$('#modal').close();break;case'close-and-route':$('#modal').close();go(el.getAttribute('href'));break;case'filter':filter=el.dataset.value;document.querySelectorAll('[data-action=filter]').forEach(x=>x.classList.toggle('active',x.dataset.value===filter));applyFilters();break;case'register':registrationForm(id);break;case'copy-pass':await copy(linkFor(passRoute({registrationId:id,accessKey:key})));break;case'feedback':feedbackForm(id,key);break;case'lookup-feedback':feedbackForm(id,'',el.dataset.lookupKey,el.dataset.program);break;case'lookup-certificate':{const r=await api.call('public.lookupCertificate',{registrationId:id,lookupKey:el.dataset.lookupKey,programId:el.dataset.program});showCertificate(r.certificate);break;}case'retry-certificate-search':searchCertificates();break;case'certificate':{const r=await api.call('public.certificate',{registrationId:id,accessKey:key});showCertificate(r.certificate);break;}case'print-certificate':window.print();break;case'print-event':window.print();break;case'fullscreen':if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();break;case'event-qr-kind':eventQrKind=el.dataset.value;render(route);break;case'show-event-qr':go('#/papar/'+encodeURIComponent(id)+'/'+el.dataset.kind+'/'+encodeURIComponent(key||''));break;case'download-event-qr':download(id+'-'+el.dataset.kind+'-qr.svg',qr(eventLink(detail.program,el.dataset.kind)),'image/svg+xml');break;case'copy-event-link':await copy(eventLink(detail.program,el.dataset.kind));break;case'self-checkin':{await api.call('public.checkIn',{registrationId:id,accessKey:key,programId:el.dataset.program,eventKey:el.dataset.eventKey});go(passRoute({registrationId:id,accessKey:key}));toast('Kehadiran anda berjaya direkodkan.');break;}case'logout':try{await api.call('admin.logout');}finally{api.logout();go('#/admin');}break;case'use-default-certificate':USTPCertificateTemplate.useDefault();break;case'certificate-settings':certificateSettingsForm();break;case'preview-certificate-settings':previewCertificateSettings();break;case'reset-feedback':modal('Reset maklum balas acara ini',`<p class="prose">${detail.report.feedback} jawapan aktif akan diarkibkan. Peserta perlu isi maklum balas semula sebelum menjana sijil. Pendaftaran, kehadiran dan rekod sijil dikekalkan.</p><p class="dialog-note mt">Jawapan asal tidak dipadam. Butang pulihkan tersedia selepas reset.</p><div class="form-actions"><button class="btn" data-action="close-modal">Batal</button><button class="btn primary" data-action="commit-reset-feedback">Reset maklum balas sekarang</button></div>`);break;case'commit-reset-feedback':{const p=detail.program,r=await api.call('admin.resetFeedback',{id:p.id,confirm:p.id,expectedEpoch:p.feedbackEpoch||0});$('#modal').close();await render(route);toast(r.archivedCount+' jawapan diarkibkan. Maklum balas aktif sudah direset.');break;}case'restore-feedback':{const p=detail.program;await api.call('admin.restoreFeedback',{id:p.id,resetId:p.feedbackLastReset.id});await render(route);toast('Jawapan lama dipulihkan; jawapan baharu dikekalkan.');break;}case'new-program':programForm();break;case'edit-program':programForm(detail.program);break;case'school-filter':schoolFilter=el.dataset.value;updateSchoolRows();break;case'admin-tab':adminTab=el.dataset.value;render(route);break;case'export':{const r=await api.call('admin.export',{id});download(r.fileName,r.csv);toast('Senarai peserta dimuat turun.');break;}case'manual-attend':await confirmAttendance(id,'','manual');break;case'commit-attendance':{const r=await api.call('admin.attend',{programId:detail.program.id,registrationId:id,accessKey:key,method:el.dataset.method});$('#modal').close();await render(route);toast(r.duplicate?'Kehadiran sudah direkodkan.':'Kehadiran '+r.name+' disahkan.');break;}case'publish-certs':modal('Terbitkan sijil program',`<p class="prose">Sijil akan dibuka kepada peserta yang melengkapkan syarat penyertaan. Selepas diterbitkan, peserta mencari nama atau emel dalam halaman acara, melengkapkan maklum balas sekali dan menjana sijil.</p><div class="callout mt">${detail.report.eligible} peserta kini layak menerima sijil.</div><div class="form-actions"><button class="btn" data-action="close-modal">Kembali</button><button class="btn primary" data-action="commit-publish" data-id="${esc(id)}">Terbitkan sijil</button></div>`);break;case'commit-publish':await api.call('admin.publishCertificates',{id});$('#modal').close();await render(route);toast('Sijil dibuka kepada peserta yang layak.');break;case'revoke':modal('Batalkan sijil',`<p class="dialog-note">Pengesahan nombor sijil ini akan memaparkan status dibatalkan.</p><form id="revoke-form" data-id="${esc(id)}"><div class="field"><label for="revoke-reason">Sebab pembatalan</label><textarea id="revoke-reason" name="reason" required maxlength="500"></textarea></div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Kembali</button><button class="btn danger">Batalkan sijil</button></div></form>`);break;}}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(button){e.preventDefault();if(button.disabled)return;const prior=button.disabled;button.disabled=true;try{await action(button);}catch(error){if(error.requiresLogin&&route.startsWith('#/admin'))expiredAdminSession(error.message);else toast(error.message,true);}finally{button.disabled=prior;}return;}const anchor=e.target.closest('a[href^="#/"]');if(anchor&&!e.metaKey&&!e.ctrlKey){e.preventDefault();go(anchor.getAttribute('href'));}});
document.addEventListener('input',e=>{if(e.target.id==='participant-search'){participantSearch=e.target.value;$('#participant-rows').innerHTML=participantRows(detail,e.target.dataset.attendance==='true');}if(e.target.id==='certificate-search'){lookupVersion++;clearTimeout(lookupTimer);const target=$('#certificate-search-results');target.innerHTML=e.target.value.trim().length<3?'':'<p class="dialog-note mt">Mencari…</p>';lookupTimer=setTimeout(searchCertificates,300);}if(e.target.id==='school-progress-search'){schoolSearch=e.target.value;updateSchoolRows();}if(e.target.id==='program-search'){search=e.target.value;applyFilters();}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!(f instanceof HTMLFormElement))return;if(!f.reportValidity())return;const button=f.querySelector('button:not([type=button])'),error=f.querySelector('.form-error');if(button)button.disabled=true;if(error)error.textContent='';const v=Object.fromEntries(new FormData(f));try{switch(f.id){case'participant-form':{await api.call('admin.updateParticipant',{programId:detail.program.id,registrationId:f.dataset.id,name:v.name,school:v.school,schoolOther:v.schoolOther==='on',participationType:v.participationType,position:v.position});$('#modal').close();await render(route);toast('Rekod peserta dikemas kini.');break;}case'certificate-settings-form':{const settings=await USTPCertificateTemplate.settings(v,f.dataset.id,api);await api.call('admin.saveCertificateSettings',{id:f.dataset.id,settings});$('#modal').close();await render(route);toast('Tetapan sijil disimpan.');break;}case'admin-login-form':{const destination=route.startsWith('#/admin')?route:'#/admin';await api.call('admin.login',{email:v.email,pin:v.pin});f.reset();shell();go(destination);toast('Selamat datang ke ruang pengurusan.');break;}case'registration-form':{const r=await api.call('public.register',{programId:f.dataset.id,name:v.name,email:v.email,school:v.school,participationType:v.participationType,position:v.position,formVersion:'20261104-v2',schoolDirectoryVersion:USTPSchools.version,schoolOther:v.schoolOther==='on',consent:v.consent==='on',eventKey:f.dataset.eventKey||'',entry:f.dataset.entry||'registration'});savePass(r);$('#modal').close();go(passRoute(r));toast(r.attendanceRecorded?'Pendaftaran dan kehadiran berjaya direkodkan.':'Pendaftaran berjaya. Simpan pautan penyertaan anda.');break;}case'program-form':{const payload={...v,capacity:Number(v.capacity),allowExternal:v.allowExternal==='on',feedbackRequired:v.feedbackRequired==='on',checkInOpen:v.checkInOpen==='on'};if(f.dataset.id)payload.id=f.dataset.id;const r=await api.call('admin.saveProgram',payload);$('#modal').close();adminTab='eventqr';eventQrKind='registration';go('#/admin/program/'+encodeURIComponent(r.program.id));toast('Program berjaya disimpan.');break;}case'feedback-form':await api.call(f.dataset.lookupKey?'public.lookupFeedback':'public.feedback',{registrationId:f.dataset.id,...(f.dataset.lookupKey?{lookupKey:f.dataset.lookupKey,programId:f.dataset.program}:{accessKey:f.dataset.key}),rating:Number(v.rating),comment:v.comment,suggestion:v.suggestion});$('#modal').close();if(f.dataset.lookupKey)await searchCertificates();else await render(route);toast('Terima kasih. Maklum balas anda diterima.');break;case'verify-form':await checkCertificate(v.id.trim());break;case'revoke-form':await api.call('admin.revokeCertificate',{id:f.dataset.id,reason:v.reason});$('#modal').close();await render(route);toast('Sijil dibatalkan dan status pengesahan dikemas kini.');break;}}catch(err){if(err.requiresLogin&&route.startsWith('#/admin'))expiredAdminSession(err.message);else if(error){error.textContent=err.message;if(err.code==='ALREADY_REGISTERED'&&f.id==='registration-form'){const a=document.createElement('a');a.className='btn mt';a.href='#/program/'+encodeURIComponent(f.dataset.id)+'/rekod';a.textContent='Cari rekod pendaftaran saya';error.appendChild(a);}}else toast(err.message,true);}finally{if(button)button.disabled=false;}});
$('#shade').addEventListener('click',()=>document.body.classList.remove('menu-open'));

window.addEventListener('hashchange',()=>{if(!api.embedded)render(location.hash||'#/');});
async function start(){if(api.embedded){try{const config=await api.call('public.config');if(config.publicUrl)api.publicUrl=config.publicUrl;api.isLive=config.mode==='live';api.adminUrl=config.adminUrl||'';api.adminLoginMode=config.adminLoginMode||'google';}catch{}google.script.history.setChangeHandler(e=>render('#'+(e.location.hash||'/')));google.script.url.getLocation(l=>render('#'+(l.hash||'/')));}else render(location.hash||'#/');}
let syncingAdmin=false;
async function syncAdmin(){
 if(syncingAdmin||!api.isAdmin||!route.startsWith('#/admin')||document.hidden||$('#modal').open||document.querySelector('button:disabled')||document.activeElement?.matches('input,textarea,select'))return;
 syncingAdmin=true;const stamp=generation,currentRoute=route;
 try{const parts=route.replace(/^#\/?/,'').split('/').map(decodeURIComponent);let html;if(parts[1]==='program'&&parts[2]){const next=await api.call('admin.program',{id:parts[2]});if(stamp!==generation||currentRoute!==route)return;detail=next;html=adminProgram(next);}else{const next=await api.call('admin.dashboard');if(stamp!==generation||currentRoute!==route)return;html=adminDashboard(next);}if($('#modal').open||document.activeElement?.matches('input,textarea,select'))return;const y=window.scrollY;$('#main').innerHTML=html;window.scrollTo({top:y,behavior:'instant'});if($('#sync-status'))$('#sync-status').textContent='Dikemas kini '+new Date().toLocaleTimeString('ms-MY',{timeZone:'Asia/Kuala_Lumpur'})+' · automatik setiap 20 saat';}
 catch(e){if(e.requiresLogin&&route.startsWith('#/admin'))expiredAdminSession(e.message);else if($('#sync-status'))$('#sync-status').textContent='Kemas kini tertangguh: '+e.message;}
 finally{syncingAdmin=false;}
}
USTPCertificateTemplate.bind();
setInterval(syncAdmin,20000);
let syncingPublic=false;setInterval(async()=>{if(syncingPublic||document.hidden||!['#/','#/program','#/dapatkan-sijil'].includes(route)||$('#modal').open||document.activeElement?.matches('input,textarea,select'))return;syncingPublic=true;const stamp=generation;try{const next=await api.call('public.catalog');if(stamp!==generation||$('#modal').open||document.activeElement?.matches('input,textarea,select'))return;programs=next;$('#main').innerHTML=route==='#/'?home():route==='#/program'?catalogue():certificateCatalogue();if(route==='#/program')applyFilters();}catch{}finally{syncingPublic=false;}},60000);
start();
})();
